```js
// Slab entry/exit times for the ball's box sweeping along (px,py)->(x,y).
// Returns null if the swept segment never overlaps the brick.
function sweptInterval(ball, prevX, prevY, brick) {
  const vx = ball.x - prevX; // per-frame displacement
  const vy = ball.y - prevY;
  let txIn, txOut, tyIn, tyOut;
  if (vx === 0) {
    if (ball.x - ball.r >= brick.x + brick.w || ball.x + ball.r <= brick.x) return null;
    txIn = -Infinity; txOut = Infinity;
  } else {
    txIn = (brick.x - (prevX + ball.r)) / vx;      // leading edge crosses near edge
    txOut = (brick.x + brick.w - (prevX - ball.r)) / vx; // trailing edge crosses far edge
    if (txIn > txOut) [txIn, txOut] = [txOut, txIn];
  }
  if (vy === 0) {
    if (ball.y - ball.r >= brick.y + brick.h || ball.y + ball.r <= brick.y) return null;
    tyIn = -Infinity; tyOut = Infinity;
  } else {
    tyIn = (brick.y - (prevY + ball.r)) / vy;
    tyOut = (brick.y + brick.h - (prevY - ball.r)) / vy;
    if (tyIn > tyOut) [tyIn, tyOut] = [tyOut, tyIn];
  }
  const tIn = Math.max(txIn, tyIn);
  const tOut = Math.min(txOut, tyOut);
  if (tIn > tOut) return null;
  if (tOut < 0 || tIn > 1) return null;
  return { tIn, tOut };
}
```

Note : les formules avec le bord menant/arrière et l'échange si négatif. Pour vx > 0 : txIn = (brick.x - (prevX + r))/vx (bord droit franchit le bord gauche), txOut = (brick.x + w - (prevX - r))/vx (bord gauche franchit le bord droit). Pour vx < 0, ces formules donnent txIn > txOut, donc on échange — c'est standard.

