function resolveBricks(state, prevX, prevY) {
  const ball = state.ball;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const iv = sweptInterval(ball, prevX, prevY, brick);
    if (iv) hits.push({ brick, iv });
  }
  if (hits.length === 0) return;

  const tResolved = Math.max(0, Math.min(...hits.map((h) => h.iv.tIn)));

  const destroyed = [];
  for (const h of hits) {
    if (h.iv.tIn <= tResolved + 1e-9 && h.iv.tOut >= tResolved - 1e-9) {
      h.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(h.brick, state.combo);
      destroyed.push(h);
    }
  }

  // axis per brick
  let flipX = false, flipY = false;
  for (const h of hits) {
    const axis = collisionAxis(ball, h.brick, h.iv);
    if (axis === 'x' || axis === 'both') flipX = true;
    if (axis === 'y' || axis === 'both') flipY = true;
  }
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // push out
  for (const h of destroyed) {
    pushOut(ball, h.brick);
  }
}
