function collisionAxis(ball, brick, iv) {
  // penetrations at the current position
  const px = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const py = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  const overlapping = px > 0 && py > 0;
  if (overlapping) {
    if (Math.abs(px - py) <= 1e-6) return 'both';
    return px < py ? 'x' : 'y';
