export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;
  const vxIn = ball.vx;
  const vyIn = ball.vy;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept box test (the 12px band and the center-only x test let the
  // ball through on slow frames and at the corners; see to_fix.md D6).
  if (ball.vy > 0 && sweptInterval(ball, prevX, prevY, paddle)) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  // Bricks — swept detection, one bounce per axis per step, push-out.
  resolveBricks(state, prevX, prevY, vxIn, vyIn);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}
```

