function resolveBricks(state, prevX, prevY, vxIn, vyIn) {
  const ball = state.ball;

  // 1. Swept detection over the step segment.
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const iv = sweptInterval(ball, prevX, prevY, brick);
    if (iv) hits.push({ brick, iv });
  }
  if (hits.length === 0) return;

  // 2. Resolution time = the earliest contact along the segment.
  let tResolved = Infinity;
  for (const h of hits) tResolved = Math.min(tResolved, h.iv.tIn);
  tResolved = Math.max(0, tResolved);

  // 3. Destroy (and score) every brick whose overlap interval covers tResolved.
  for (const h of hits) {
    if (h.iv.tIn <= tResolved + EPS && h.iv.tOut >= tResolved - EPS) {
      h.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(h.brick, state.combo);
    }
  }

  // 4. Bounce axes: smallest penetration at the current spot; equal means a
  // corner (both axes). A brick not overlapped at the end (tunneling) uses
  // the axis entered last. One flip per axis per step.
  let flipX = false;
  let flipY = false;
  for (const h of hits) {
    const axis = collisionAxis(ball, h.brick, h.iv);
    if (axis === 'x') flipX = true;
    else if (axis === 'y') flipY = true;
    else { flipX = true; flipY = true; } // corner
  }
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // 5. Push the ball out of every brick it still overlaps (dead or alive).
  for (const brick of state.bricks) {
    if (collides(ball, brick)) pushOut(ball, brick, vxIn, vyIn);
  }
}
```

