// Pushes the ball out of the brick through the face it entered (opposite the
// incoming velocity along the axis), or the nearer face when its center lies
// outside the brick's slab on that axis.
function pushOut(ball, brick, vxIn, vyIn) {
  if (
    ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h
  ) {
    // y axis
    if (ball.y < brick.y) {
      ball.y = brick.y - ball.r;
    } else if (ball.y > brick.y + brick.h) {
      ball.y = brick.y + brick.h + ball.r;
    } else if (vyIn > 0) {
      ball.y = brick.y - ball.r; // came from above → exit through the top face
    } else {
      ball.y = brick.y + brick.h + ball.r; // came from below → exit through the bottom
    }
  }
  if (
    ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h
  ) {
    if (ball.x < brick.x) {
      ball.x = brick.x - ball.r;
    } else if (ball.x > brick.x + brick.w) {
      ball.x = brick.x + brick.w + ball.r;
    } else if (vxIn > 0) {
      ball.x = brick.x - ball.r; // came from the left → exit through the left face
    } else {
      ball.x = brick.x + brick.w + ball.r; // came from the right
    }
  }
}
