```js
function resolveBricks(state, prevX, prevY, vxIn, vyIn) {
  const ball = state.ball;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const iv = sweptInterval(ball, prevX, prevY, brick);
    if (iv) hits.push({ brick, iv });
  }
  if (hits.length === 0) return;

  let tResolved = Math.min(...hits.map((h) => h.iv.tIn));
  tResolved = Math.max(0, tResolved);

  let flipX = false;
  let flipY = false;
  for (const h of hits) {
    if (h.iv.tIn <= tResolved + EPS && h.iv.tOut >= tResolved - EPS) {
      h.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(h.brick, state.combo);
    }
    const axis = collisionAxis(ball, h.brick, h.iv);
    if (axis === 'x') flipX = true;
    else if (axis === 'y') flipY = true;
    else { flipX = true; flipY = true; }
  }
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  for (const h of hits) {
    if (collides(ball, h.brick)) {
      pushOut(ball, h.brick, vxIn, vyIn, collisionAxis(ball, h.brick, h.iv));
    }
  }
}
