edits.newText:
// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Slab overlap interval of the ball's box with a rectangle while the ball
// sweeps from (prevX, prevY) to its current spot. Returns
// `{ tIn, tOut, txIn, tyIn }` when the segment overlaps the rectangle at any
// time during [0, 1], else null. `tIn`/`tOut` are the entry/exit times; the
// per-axis entries are kept for the tunneling axis rule (collisionAxis).
// This is a swept AABB: a step longer than the obstacle cannot skip it.
function sweptInterval(ball, prevX, prevY, rect) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let txIn, txOut;
  if (dx === 0) {
    if (ball.x + ball.r <= rect.x || ball.x - ball.r >= rect.x + rect.w) return null;
    txIn = -Infinity;
    txOut = Infinity;
  } else {
    txIn = (rect.x - (prevX + ball.r)) / dx; // leading edge crosses the near edge
    txOut = (rect.x + rect.w - (prevX - ball.r)) / dx; // trailing edge crosses the far edge
    if (txIn > txOut) [txIn, txOut] = [txOut, txIn];
  }

  let tyIn, tyOut;
  if (dy === 0) {
    if (ball.y + ball.r <= rect.y || ball.y - ball.r >= rect.y + rect.h) return null;
    tyIn = -Infinity;
    tyOut = Infinity;
  } else {
    tyIn = (rect.y - (prevY + ball.r)) / dy;
    tyOut = (rect.y + rect.h - (prevY - ball.r)) / dy;
    if (tyIn > tyOut) [tyIn, tyOut] = [tyOut, tyIn];
  }

  const tIn = Math.max(txIn, tyIn);
  const tOut = Math.min(txOut, tyOut);
  if (tIn > tOut) return null;
  if (tOut < 0 || tIn > 1) return null;
  return { tIn, tOut, txIn, tyIn };
}

const PENETRATION_EPS = 1e-6;

// Axis of the bounce for one brick: the axis of smallest penetration at the
// current spot (equal penetrations = corner, both axes flip). When the ball
// no longer overlaps the brick at the end of the step (pure tunneling), the
// axis is the slab entered last along the swept segment.
function collisionAxis(ball, brick, iv) {
  const px = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const py = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  if (px > 0 && py > 0) {
    if (Math.abs(px - py) <= PENETRATION_EPS) return 'both';
    return px < py ? 'x' : 'y';
  }
  if (iv.txIn === -Infinity) return 'y';
  if (iv.tyIn === -Infinity) return 'x';
  if (Math.abs(iv.txIn - iv.tyIn) <= PENETRATION_EPS) return 'both';
  return iv.txIn > iv.tyIn ? 'x' : 'y';
}

// Pushes the ball out of the brick along `axis`, through the face it entered
// (opposite the incoming velocity), or the nearer face when the ball's center
// lies outside the brick's slab on that axis.
function pushOut(ball, brick, vxIn, vyIn, axis) {
  if (axis === 'x' || axis === 'both') {
    if (ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w) {
      if (ball.x < brick.x) ball.x = brick.x - ball.r;
      else if (ball.x > brick.x + brick.w) ball.x = brick.x + brick.w + ball.r;
      else if (vxIn > 0) ball.x = brick.x - ball.r;
      else ball.x = brick.x + brick.w + ball.r;
    }
  }
  if (axis === 'y' || axis === 'both') {
    if (ball.y + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h) {
      if (ball.y < brick.y) ball.y = brick.y - ball.r;
      else if (ball.y > brick.y + brick.h) ball.y = brick.y + brick.h + ball.r;
      else if (vyIn > 0) ball.y = brick.y - ball.r;
      else ball.y = brick.y + brick.h + ball.r;
    }
  }
}

// Brick bounce resolution: swept detection, one flip per axis per step, and a
// push-out that leaves the ball outside every brick it overlaps. Every brick
// hit at the resolution time breaks and scores (seam hits break both).
function resolveBricks(state, prevX, prevY, vxIn, vyIn) {
  const { ball, bricks } = state;

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const iv = sweptInterval(ball, prevX, prevY, brick);
    if (iv) hits.push({ brick, iv });
  }
  if (hits.length === 0) return;

  // Earliest contact along the segment (clamped to the frame).
  let tResolved = Infinity;
  for (const h of hits) tResolved = Math.min(tResolved, h.iv.tIn);
  tResolved = Math.max(0, tResolved);

  let flipX = false;
  let flipY = false;
  for (const h of hits) {
    // Destroy and score the bricks actually hit at the resolution time (a
    // brick only crossed geometrically later in the segment stays intact).
    if (h.iv.tIn <= tResolved + PENETRATION_EPS && h.iv.tOut >= tResolved - PENETRATION_EPS) {
      h.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(h.brick, state.combo);
    }
    const axis = collisionAxis(ball, h.brick, h.iv);
    if (axis === 'x') flipX = true;
    else if (axis === 'y') flipY = true;
    else {
      flipX = true;
      flipY = true;
    }
  }

  // One bounce per pass per axis: two overlapping bricks on a seam must not
  // cancel each other's flip.
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // Push the ball out of every brick it still overlaps (dead or alive).
  for (const h of hits) {
    if (collides(ball, h.brick)) {
      pushOut(ball, h.brick, vxIn, vyIn, collisionAxis(ball, h.brick, h.iv));
    }
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks. Returns `true` if the
// ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;
  const vxIn = ball.vx;
  const vyIn = ball.vy;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept box test over the whole step (a 12px band and a center-only
  // x test would let the ball through on slow frames and at the corners).
  if (ball.vy > 0 && sweptInterval(ball, prevX, prevY, paddle)) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: swept bounce, one flip per axis, push-out.
  resolveBricks(state, prevX, prevY, vxIn, vyIn);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

