function sweptInterval(ball, prevX, prevY, rect) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let txIn, txOut;
  if (dx === 0) {
    if (ball.x + ball.r <= rect.x || ball.x - ball.r >= rect.x + rect.w) return null;
    txIn = -Infinity;
    txOut = Infinity;
  } else {
    txIn = (rect.x - (prevX + ball.r)) / dx; // leading edge crosses the near edge
    txOut = (rect.x + rect.w - (prevX - ball.r)) / dx; // trailing edge crosses the far edge
    if (txIn > txOut) [txIn, txOut] = [txOut, txIn];
  }

  let tyIn, tyOut;
  if (dy === 0) {
    if (ball.y + ball.r <= rect.y || ball.y - ball.r >= rect.y + rect.h) return null;
    tyIn = -Infinity;
    tyOut = Infinity;
  } else {
    tyIn = (rect.y - (prevY + ball.r)) / dy;
    tyOut = (rect.y + rect.h - (prevY - ball.r)) / dy;
    if (tyIn > tyOut) [tyIn, tyOut] = [tyOut, tyIn];
  }

  const tIn = Math.max(txIn, tyIn);
  const tOut = Math.min(txOut, tyOut);
  if (tIn > tOut) return null;
  if (tOut < 0 || tIn > 1) return null;
  return { tIn, tOut, txIn, tyIn };
}
