const PENETRATION_EPS = 1e-6;

// Axis of the bounce for one brick, decided at the FIRST CONTACT position
// (cx, cy) — where the ball was at `tResolved` — not at the final spot: a
// ball that enters a brick through its bottom face while already sliding
// sideways would otherwise read a smaller X penetration and bounce off the
// wrong face. Penetrations: the axis with the smallest overlap; equal
// overlaps mean a corner and both axes flip. A "full" overlap (the ball
// entirely inside the brick's slab on an axis) carries no information: if
// both are full, the incoming velocity decides. As a fallback for a pure
// tunneling contact, the axis is the slab entered last along the segment.
function collisionAxis(ball, brick, iv, cx, cy) {
  const px = Math.min(cx + ball.r, brick.x + brick.w) - Math.max(cx - ball.r, brick.x);
  const py = Math.min(cy + ball.r, brick.y + brick.h) - Math.max(cy - ball.r, brick.y);

  const fullX = px >= 2 * ball.r - PENETRATION_EPS;
  const fullY = py >= 2 * ball.r - PENETRATION_EPS;

  if (px > 0 && py > 0) {
    if (fullX && fullY) return Math.abs(ball.vy) > Math.abs(ball.vx) ? 'y' : 'x';
    if (fullX) return 'y';
    if (fullY) return 'x';
    if (Math.abs(px - py) <= PENETRATION_EPS) return 'both';
    return px < py ? 'x' : 'y';
  }
  if (px > 0) return 'y'; // entered through the top/bottom face
  if (py > 0) return 'x'; // entered through a side face
  if (iv.txIn === -Infinity) return 'y';
  if (iv.tyIn === -Infinity) return 'x';
  if (Math.abs(iv.txIn - iv.tyIn) <= PENETRATION_EPS) return 'both';
  return iv.txIn > iv.tyIn ? 'x' : 'y';
}

