// Earliest contact along the segment (clamped to the frame).
let tResolved = Infinity;
for (const h of hits) tResolved = Math.min(tResolved, h.iv.tIn);
tResolved = Math.max(0, tResolved);

// Ball position at the moment of first contact: the axis decision must be
// made there, not at the final spot (see collisionAxis).
const cx = prevX + (ball.x - prevX) * tResolved;
const cy = prevY + (ball.y - prevY) * tResolved;

let flipX = false;
let flipY = false;
for (const h of hits) {
  // Destroy and score the bricks actually hit at the resolution time (a
  // brick only crossed geometrically later in the segment stays intact).
  if (h.iv.tIn <= tResolved + PENETRATION_EPS && h.iv.tOut >= tResolved - PENETRATION_EPS) {
    h.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(h.brick, state.combo);
  }
  const axis = collisionAxis(ball, h.brick, h.iv, cx, cy);
  if (axis === 'x') flipX = true;
  else if (axis === 'y') flipY = true;
  else {
    flipX = true;
    flipY = true;
  }
}

// One bounce per pass per axis: two overlapping bricks on a seam must not
// cancel each other's flip.
if (flipX) ball.vx = -ball.vx;
if (flipY) ball.vy = -ball.vy;

// Push the ball out of every brick it still overlaps (dead or alive).
for (const h of hits) {
  if (collides(ball, h.brick)) {
    pushOut(ball, h.brick, vxIn, vyIn, collisionAxis(ball, h.brick, h.iv, cx, cy));
  }
}

